    jdbcTemplate.execute("UPDATE customer_orders SET ordinary_price_minor = CAST(CAST(ordinary_price AS numeric) * 100 AS bigint) WHERE ordinary_price_minor IS NULL AND ordinary_price IS NOT NULL AND NOT EXISTS (SELECT 1 FROM money_migration_ledger WHERE migration_key = 'core-invoice-shadow-v1')");
