    jdbcTemplate.execute("CREATE OR REPLACE FUNCTION guard_product_money_integrity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.currency_code IS DISTINCT FROM 'SEK' OR NEW.price IS NULL OR NEW.discount_price IS NULL THEN RAISE EXCEPTION 'Invalid product currency or amount' USING ERRCODE = '23514'; END IF; IF TG_OP = 'INSERT' THEN IF (NEW.price_minor IS NOT NULL AND NEW.price_minor IS DISTINCT FROM CAST(NEW.price AS numeric) * 100) OR (NEW.discount_price_minor IS NOT NULL AND NEW.discount_price_minor IS DISTINCT FROM CAST(NEW.discount_price AS numeric) * 100) THEN RAISE EXCEPTION 'Invalid product money shadow' USING ERRCODE = '23514'; END IF; ELSE IF OLD.currency_code IS DISTINCT FROM 'SEK' OR OLD.price_minor IS DISTINCT FROM CAST(OLD.price AS numeric) * 100 OR OLD.discount_price_minor IS DISTINCT FROM CAST(OLD.discount_price AS numeric) * 100 THEN RAISE EXCEPTION 'Stored product money integrity violation' USING ERRCODE = '23514'; END IF; IF NEW.price_minor IS NULL OR NEW.discount_price_minor IS NULL OR (NEW.price_minor IS DISTINCT FROM CAST(NEW.price AS numeric) * 100 AND (NEW.price_minor IS DISTINCT FROM OLD.price_minor OR NEW.price IS NOT DISTINCT FROM OLD.price)) OR (NEW.discount_price_minor IS DISTINCT FROM CAST(NEW.discount_price AS numeric) * 100 AND (NEW.discount_price_minor IS DISTINCT FROM OLD.discount_price_minor OR NEW.discount_price IS NOT DISTINCT FROM OLD.discount_price)) THEN RAISE EXCEPTION 'Invalid product money shadow' USING ERRCODE = '23514'; END IF; END IF; RETURN NEW; END; $$");
