    jdbcTemplate.execute("CREATE OR REPLACE FUNCTION guard_journal_money_integrity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND (OLD.debit IS NULL OR OLD.credit IS NULL OR OLD.debit_minor IS DISTINCT FROM OLD.debit::numeric * 100 OR OLD.credit_minor IS DISTINCT FROM OLD.credit::numeric * 100 OR OLD.currency_code IS DISTINCT FROM 'SEK' OR OLD.debit < 0 OR OLD.credit < 0 OR (OLD.debit > 0 AND OLD.credit > 0)) THEN RAISE EXCEPTION 'Stored journal money integrity violation' USING ERRCODE = '23514'; END IF; IF NEW.debit IS NULL OR NEW.credit IS NULL OR NEW.currency_code IS DISTINCT FROM 'SEK' OR NEW.debit < 0 OR NEW.credit < 0 OR (NEW.debit > 0 AND NEW.credit > 0) OR (NEW.debit_minor IS NOT NULL AND NEW.debit_minor IS DISTINCT FROM NEW.debit::numeric * 100) OR (NEW.credit_minor IS NOT NULL AND NEW.credit_minor IS DISTINCT FROM NEW.credit::numeric * 100) OR (TG_OP = 'UPDATE' AND (NEW.debit_minor IS NULL OR NEW.credit_minor IS NULL)) THEN RAISE EXCEPTION 'Invalid journal money values' USING ERRCODE = '23514'; END IF; RETURN NEW; END; $$");
