    jdbcTemplate.execute("CREATE OR REPLACE FUNCTION sync_supplier_payment_shadow_fields() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.amount IS NULL OR OLD.amount <> TRUNC(CAST(OLD.amount AS numeric)) OR OLD.amount_minor IS DISTINCT FROM CAST(OLD.amount AS numeric) * 100 OR OLD.currency_code IS DISTINCT FROM 'SEK' THEN RAISE EXCEPTION 'Stored supplier payment money integrity violation' USING ERRCODE = '23514'; END IF; END IF; IF NEW.amount IS NULL OR NEW.amount <> TRUNC(CAST(NEW.amount AS numeric)) OR NEW.currency_code IS DISTINCT FROM 'SEK' OR (NEW.amount_minor IS NOT NULL AND NEW.amount_minor IS DISTINCT FROM CAST(NEW.amount AS numeric) * 100) OR (TG_OP = 'UPDATE' AND NEW.amount_minor IS NULL) THEN RAISE EXCEPTION 'Invalid supplier payment money values' USING ERRCODE = '23514'; END IF; NEW.amount_minor = CAST(CAST(NEW.amount AS numeric) * 100 AS bigint); RETURN NEW; END; $$");
