    jdbcTemplate.execute("CREATE OR REPLACE FUNCTION reserve_journal_voucher() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE registered_xid bigint; already_sealed boolean; BEGIN IF NEW.voucher_number IS NULL OR btrim(NEW.voucher_number) = '' THEN RAISE EXCEPTION 'Journal voucher number is required' USING ERRCODE = '23514'; END IF; INSERT INTO journal_voucher_registry (voucher_number, posting_xid, sealed) VALUES (NEW.voucher_number, txid_current(), false) ON CONFLICT (voucher_number) DO NOTHING; SELECT posting_xid, sealed INTO registered_xid, already_sealed FROM journal_voucher_registry WHERE voucher_number = NEW.voucher_number FOR UPDATE; IF NOT FOUND OR already_sealed OR registered_xid <> txid_current() THEN RAISE EXCEPTION 'Posted voucher number cannot be reused; use a correction voucher' USING ERRCODE = '23514'; END IF; RETURN NEW; END; $$");
